'use strict';
const {departments,documents,checkedAt}=window.POLICY_DATA;
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=u=>{try{const v=new URL(u);return /^https?:$/.test(v.protocol)?v.href:'#';}catch{return '#';}};
const link=(url,title,cls='')=>`<a href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer" class="${cls}">${esc(title)} <span aria-hidden="true">↗</span></a>`;
const deptById=Object.fromEntries(departments.map(d=>[d.id,d]));
const state={dept:'all',status:'all',q:'',topic:'all',series:'all',sort:'department',view:'documents'};
let activeDoc=null,toastTimer;
const dateLabel=d=>d.date?d.date.replaceAll('-','.'):'日期待核实';
const badge=d=>`<span class="verification ${d.verification==='lead'?'lead':''}">${d.verification==='official'?'官网核验':'待补原文'}</span>`;
const docsFor=d=>documents.filter(x=>x.departmentId===d.id);
const deptStatus=d=>docsFor(d).some(x=>x.verification==='official')?'official':docsFor(d).length?'lead':'missing';
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200);}
function setDept(id){state.dept=id;render();}
function reset(){Object.assign(state,{dept:'all',status:'all',q:'',topic:'all',series:'all',sort:'department'});$('#search').value='';$('#series').value='all';$('#sort').value='department';render();}
function documentMatches(d){if(state.dept!=='all'&&d.departmentId!==state.dept)return false;if(state.status==='missing')return false;if(state.status!=='all'&&state.status!==d.verification)return false;if(state.series!=='all'&&d.series!==state.series)return false;const hay=[d.title,d.number,deptById[d.departmentId].name,d.summary,d.tags.join(' '),d.body].join(' ').toLowerCase();if(state.q&&!hay.includes(state.q.toLowerCase()))return false;if(state.topic!=='all'&&!hay.includes(state.topic))return false;return true;}
function missingMatches(d){if(docsFor(d).length||!['all','missing'].includes(state.status)||state.series!=='all'||state.topic!=='all')return false;if(state.dept!=='all'&&state.dept!==d.id)return false;return !state.q||(d.name+' '+d.id).toLowerCase().includes(state.q.toLowerCase());}
function card(d){return `<button class="file-card" data-doc="${esc(d.id)}" aria-label="查看${esc(d.number)}：${esc(d.title)}"><div class="card-top"><span class="card-dept"><span>${d.departmentId}</span>${esc(deptById[d.departmentId].shortName||deptById[d.departmentId].name)}</span>${badge(d)}</div><div class="file-number">${esc(d.number)}</div><h3>${esc(d.shortTitle||d.title.replace(/^教育部办公厅等[一二三四五六七八九十]+部门关于|^教育部等[一二三四五六七八九十]+部门关于|^教育部办公厅关于|^教育部关于/,'').replace(/的通知$|的意见$|的决定$/,''))}</h3><p>${esc(d.summary)}</p><div class="card-tags"><span class="nature">${esc(d.nature)}</span>${d.tags.slice(0,2).map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="card-bottom"><span>${dateLabel(d)}${d.date?' · 成文':''}</span><span class="read-more">阅读详情 <b>↗</b></span></div></button>`;}
function missingCard(d){return `<button class="file-card missing-card" data-missing="${d.id}" aria-label="查看${esc(d.name)}的检索记录"><div class="card-top"><span class="card-dept">${d.id} / ${esc(d.shortName||d.name)}</span></div><h3>暂未检索到公开的1号文件</h3><p>已进行定向检索，暂无可核实的2026年1号文件。<br>此状态不代表该司局未发文。</p><div class="card-bottom"><span>检索截至 2026.11.17</span><span class="read-more">查看检索记录 ↗</span></div></button>`;}
function renderSidebar(){$('#all-count').textContent=documents.length;$('#all-departments').classList.toggle('selected',state.dept==='all');$('#all-departments').setAttribute('aria-pressed',state.dept==='all');$('#department-list').innerHTML=`<button class="dept-item mobile-all ${state.dept==='all'?'selected':''}" data-dept="all" style="${window.innerWidth>800?'display:none':''}"><span>全部司局</span><span class="dept-count">${documents.length}</span></button>`+departments.map(d=>{const n=docsFor(d).length,st=deptStatus(d);return `<button class="dept-item ${state.dept===d.id?'selected':''}" data-dept="${d.id}" aria-pressed="${state.dept===d.id}" title="${esc(d.name)}"><span>${esc(d.shortName||d.name)}</span>${n?`<span class="dept-count">${n}</span>`:`<span class="dept-marker"></span>`}</button>`;}).join('');}
function render(){renderSidebar();$$('[data-status]').forEach(b=>{b.classList.toggle('active',b.dataset.status===state.status);b.setAttribute('aria-pressed',b.dataset.status===state.status);});$$('[data-topic]').forEach(b=>{b.classList.toggle('active',b.dataset.topic===state.topic);b.setAttribute('aria-pressed',b.dataset.topic===state.topic);});$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));const coverage=state.view==='coverage';$('#catalog-title').textContent=coverage?'27 个司局的检索进度':state.dept==='all'?'2026 年文件索引':(deptById[state.dept].shortName||deptById[state.dept].name);$('#results').hidden=coverage;$('#coverage-view').hidden=!coverage;$('#topic-bar').hidden=coverage;$('.selects').hidden=coverage;$('.results-note').hidden=coverage;const filtered=documents.filter(documentMatches).sort((a,b)=>{if(state.sort==='department')return departments.findIndex(d=>d.id===a.departmentId)-departments.findIndex(d=>d.id===b.departmentId)||(a.verification==='official'?0:1)-(b.verification==='official'?0:1)||a.number.localeCompare(b.number,'zh');if(!a.date)return 1;if(!b.date)return -1;return state.sort==='newest'?b.date.localeCompare(a.date):a.date.localeCompare(b.date);});const missing=departments.filter(missingMatches);$('#clear-button').hidden=state.dept==='all'&&state.status==='all'&&!state.q&&state.topic==='all'&&state.series==='all';if(!coverage){const official=filtered.filter(d=>d.verification==='official').length;$('#results-count').textContent=`${filtered.length} 份文件${filtered.length?` · ${official} 份官网核验` : ''}${missing.length?` · ${missing.length} 个司局未检索到`:''}`;$('#results').innerHTML=filtered.map(card).join('')+missing.map(missingCard).join('');if(!filtered.length&&!missing.length)$('#results').innerHTML='<div class="empty-state"><strong>没有符合条件的结果</strong><p>试试更短的关键词，或清除文号、司局和主题筛选。</p><button class="button button-ghost" data-reset>清除全部筛选</button></div>';}else{const ds=departments.filter(d=>(state.dept==='all'||state.dept===d.id)&&(state.status==='all'||(state.status==='missing'?deptStatus(d)==='missing':docsFor(d).some(x=>x.verification===state.status)))&&(!state.q||(d.name+' '+d.id+' '+docsFor(d).map(x=>x.number+' '+x.title).join(' ')).toLowerCase().includes(state.q.toLowerCase())));$('#results-count').textContent=`显示 ${ds.length} / ${departments.length} 个司局 · 以本轮检索结果为准`;$('#coverage-view').innerHTML=ds.length?`<table class="coverage-table"><thead><tr><th>索引</th><th>职能司局</th><th>检索状态</th><th>文件 / 线索</th></tr></thead><tbody>${ds.map(d=>{const s=deptStatus(d),n=docsFor(d);return `<tr><td>${d.id}</td><td class="coverage-name">${esc(d.name)}</td><td><span class="coverage-state ${s}">${s==='official'?'已检到官网原文':s==='lead'?'仅其他官方线索':'未检索到'}</span></td><td><button ${n.length?`data-coverage="${d.id}"`:`data-missing="${d.id}"`}>${n.length?`${n.filter(x=>x.verification==='official').length} 原文 / ${n.filter(x=>x.verification==='lead').length} 线索`:'检索记录'} ↗</button></td></tr>`;}).join('')}</tbody></table>`:'<div class="empty-state"><strong>没有符合条件的司局</strong><button class="button button-ghost" data-reset>清除筛选</button></div>';}}
function showDialog(dialog){if(!dialog.open)dialog.showModal();document.body.classList.add('modal-open');dialog.scrollTop=0;}
function showDocument(id){const d=documents.find(x=>x.id===id);if(!d)return;activeDoc=d;$('#detail-position').textContent=d.number;$('#copy-button').hidden=false;$('#print-button').hidden=false;const dept=deptById[d.departmentId];const meta=[['业务司局',dept.name+(d.verification==='lead'?'（暂归）':'')],['发文机构',d.issuer],['成文日期',d.date?(d.date+(d.verification==='lead'?'（转引来源）':'')):'尚未核实'],['发布日期',d.publishedDate||'未确认'],['生成日期',d.generatedDate||'未确认'],['文号系列',d.series+' · '+d.nature]];
const sources=[{title:d.verification==='official'?'教育部官网原文':(d.sourceType||'其他官方来源'),url:d.url},...(d.sources||[]),...(d.supportingSources||[])].filter((v,i,arr)=>arr.findIndex(x=>x.url===v.url)===i);
const sourceRows=sources.map(s=>`<div class="source-row"><small>${d.verification==='official'?'原始来源':'线索来源 · 尚待教育部原文'}</small>${link(s.url,s.title)}<div class="url">${esc(s.url)}</div></div>`).join('');
const attachments=(d.attachments||[]).map((a,i)=>`<div class="source-row"><small>附件 ${String(i+1).padStart(2,'0')}</small>${link(a.url,a.title||a.name||'查看附件')}</div>`).join('');
const body=(d.body||'').trim();
$('#detail-content').innerHTML=`<div class="detail-meta-top"><span class="dept-label">${d.departmentId} / ${esc(dept.shortName||dept.name)}</span>${badge(d)}</div><div class="detail-number">${esc(d.number)}</div><h2 id="detail-title">${esc(d.title)}</h2><dl class="detail-meta-grid">${meta.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v||'未确认')}</dd></div>`).join('')}</dl><div class="detail-tags">${d.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div>${d.verification==='lead'?`<div class="reading-note lead">待补教育部官网原文：${esc(d.verificationNote||'当前依据其他官方来源整理，尚未检到教育部官网原文。')} 司局暂按文号及业务内容归类。</div>`:''}<div class="detail-tabs" role="tablist" aria-label="文件内容"><button class="active" role="tab" id="tab-summary" aria-selected="true" aria-controls="panel-summary" data-panel="summary">内容摘要</button><button role="tab" id="tab-body" aria-selected="false" aria-controls="panel-body" tabindex="-1" data-panel="body">${body?'正文阅读':'原文状态'}</button><button role="tab" id="tab-sources" aria-selected="false" aria-controls="panel-sources" tabindex="-1" data-panel="sources">来源与附件${d.attachments.length?` (${d.attachments.length})`:''}</button></div><section class="detail-panel" id="panel-summary" role="tabpanel" aria-labelledby="tab-summary" data-panel-content="summary"><h3>文件讲了什么</h3><p class="summary-text">${esc(d.summary)}</p><h3>内容要点</h3><ol class="key-points">${d.points.map(p=>`<li>${esc(typeof p==='string'?p:p.text||p.description||JSON.stringify(p))}</li>`).join('')}</ol><div class="reading-note">本页摘要、要点及标签为资料整理，不构成官方解读。“1号”是该文号系列的编号，不能据此判定文件的政策层级或年度重要性。</div><div class="source-actions">${link(d.url,d.verification==='official'?'查看教育部原文':'查看线索来源','button button-primary')}<button class="button button-ghost" data-panel="body">${body?'在本站阅读正文':'查看原文状态'} →</button></div></section><section class="detail-panel" id="panel-body" role="tabpanel" aria-labelledby="tab-body" data-panel-content="body" hidden>${body?`<div class="reading-note">${d.verification==='official'?'教育部公开公文文字快照；段落格式经过整理，附件请在“来源与附件”中查看。':'以下文字来自已公开的其他官方来源，尚待教育部官网原文校对。'} ${esc(d.bodyNote||'')}</div><div class="body-text">${body.split(/\n+/).filter(Boolean).map(p=>/^[一二三四五六七八九十]+、/.test(p.trim())&&p.length<60?`<h4>${esc(p)}</h4>`:`<p>${esc(p)}</p>`).join('')}</div>`:`<div class="reading-note lead">尚未取得可核验的公文正文。当前收录的是其他官方来源中的标题、文号与相关引用，不将新闻或引用内容作为文件全文。</div><p class="summary-text">可通过下方来源链接核查现有线索。</p>`}<div class="source-actions">${link(d.url,d.verification==='official'?'核对官方原文':'查看公开来源','button button-primary')}</div></section><section class="detail-panel" id="panel-sources" role="tabpanel" aria-labelledby="tab-sources" data-panel-content="sources" hidden><h3>核验依据</h3><div class="reading-note ${d.verification==='lead'?'lead':''}">${esc(d.verificationNote||'已核对官方页面发文字号及正文。')}${d.index?`<br>教育部信息索引：${esc(d.index)}`:''}<br>检索核查日期：${checkedAt}${d.sourcePublishedDate?`<br>线索页面发布日期：${esc(d.sourcePublishedDate)}（非公文成文日期）`:''}</div>${sourceRows}<h3>原站附件</h3>${attachments||'<p class="reading-note">当前原文未提取到单独附件链接。正文内附件或后续更新请在原站核对。</p>'}<div class="source-row"><small>司局入口</small>${link(dept.url,dept.name)}</div></section>`;
showDialog($('#detail-dialog'));history.replaceState(null,'','#doc='+encodeURIComponent(id));}
function showMissing(id){const d=deptById[id];if(!d)return;activeDoc=null;$('#copy-button').hidden=true;$('#print-button').hidden=true;$('#detail-position').textContent=d.name;$('#detail-content').innerHTML=`<div class="section-kicker">${d.id} / SEARCH LOG</div><h2 id="detail-title">${esc(d.name)}</h2><div class="reading-note">本轮未检索到可核实的 2026 年“1号”文件。检索状态不等于未发文，不代表文件不存在或未向其他渠道发布。</div><h3>核查说明</h3><p class="summary-text">${esc(d.note)}</p><h3>定向检索词</h3><ol class="key-points">${(d.searches||[]).map(q=>`<li>${esc(q)}</li>`).join('')}</ol><p class="reading-note">核查日期：${checkedAt}。已排除正文中引用的往年1号文件、信息索引中的“0001”以及公报期号。</p><div class="source-actions">${link(d.url,'查看该司局官网栏目','button button-primary')}</div>`;showDialog($('#detail-dialog'));}
function setPanel(name){$$('[data-panel-content]').forEach(p=>p.hidden=p.dataset.panelContent!==name);$$('.detail-tabs [data-panel]').forEach(b=>{const on=b.dataset.panel===name;b.classList.toggle('active',on);b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;});}
function exportCSV(){const rows=[['司局','核验状态','发文字号','文号系列','文件名称','成文日期','发布日期','文件性质','摘要','来源URL','检索日期'],...documents.map(d=>[deptById[d.departmentId].name,d.verification==='official'?'教育部官网核验':'待补教育部原文',d.number,d.series,d.title,d.date||'待核实',d.publishedDate||'未确认',d.nature,d.summary,d.url,checkedAt]),...departments.filter(d=>!docsFor(d).length).map(d=>[d.name,'未检索到','','','','','','',d.note,d.url,checkedAt])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='教育部2026年一号文件索引_'+checkedAt+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('已导出全部文件、线索及未检索到司局');}
$('#stat-depts').textContent=departments.length;$('#stat-docs').textContent=documents.filter(d=>d.verification==='official').length;$('#stat-covered').textContent=departments.filter(d=>deptStatus(d)==='official').length;$('#stat-leads').textContent=documents.filter(d=>d.verification==='lead').length;
$('#all-departments').onclick=()=>setDept('all');$('#search').addEventListener('input',e=>{state.q=e.target.value.trim();render();});$('#series').onchange=e=>{state.series=e.target.value;render();};$('#sort').onchange=e=>{state.sort=e.target.value;render();};$('#clear-button').onclick=reset;$('#export-button').onclick=exportCSV;$('#export-button').title='导出全部文件、线索及未检索到司局，不受当前筛选影响';$('#method-button').onclick=()=>showDialog($('#method-dialog'));$('#back-top').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});$('.brand').onclick=e=>{e.preventDefault();state.view='documents';reset();window.scrollTo({top:0,behavior:'smooth'});};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.dept)setDept(b.dataset.dept);if(b.dataset.status){state.status=b.dataset.status;render();}if(b.dataset.topic){state.topic=b.dataset.topic;render();}if(b.dataset.view){state.view=b.dataset.view;render();$('#index').scrollIntoView({behavior:'smooth',block:'start'});}if(b.dataset.doc)showDocument(b.dataset.doc);if(b.dataset.missing)showMissing(b.dataset.missing);if(b.dataset.coverage){state.view='documents';Object.assign(state,{dept:b.dataset.coverage,status:'all',q:'',series:'all',topic:'all'});$('#search').value='';$('#series').value='all';render();}if(b.hasAttribute('data-reset'))reset();if(b.dataset.panel)setPanel(b.dataset.panel);if(b.classList.contains('close-dialog'))b.closest('dialog').close();});
$$('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});d.addEventListener('close',()=>{if(!$$('dialog[open]').length)document.body.classList.remove('modal-open');if(d.id==='detail-dialog'){activeDoc=null;if(location.hash.startsWith('#doc='))history.replaceState(null,'',location.pathname+location.search);}});});
$('#copy-button').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);toast('文件链接已复制');}catch{toast('复制受浏览器限制，请复制地址栏中的链接');}};$('#print-button').onclick=()=>window.print();
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!$$('dialog[open]').length){e.preventDefault();$('#search').focus();}if(e.target.matches('.detail-tabs [role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=$$('.detail-tabs [role="tab"]');let i=tabs.indexOf(e.target);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;setPanel(tabs[i].dataset.panel);tabs[i].focus();}});
window.addEventListener('resize',()=>{const b=$('.mobile-all');if(b)b.style.display=window.innerWidth>800?'none':'';});
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#doc='))showDocument(decodeURIComponent(location.hash.slice(5)));});
render();if(location.hash.startsWith('#doc='))showDocument(decodeURIComponent(location.hash.slice(5)));
